from itertools import product

def has_zero_sum_subsequence(seq):
    n = len(seq)
    for length in range(1, n + 1):
        for start in range(n - length + 1):
            for signs in product([-1, 1], repeat=length):
                if sum(signs[i] * seq[start + i] for i in range(length)) == 0:
                    return True
    return False

max_length = 63
max_value = 32

